    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '0f544dce-a115-5ce5-832b-8cfe5a4e0b45', '0ebbaafc-f24d-5601-8c9a-140abf0b3b54', 'en', 'Tsunami', 'A tsunami is a series of long waves caused by a large, sudden movement of water. An undersea earthquake can move the seafloor and push the water above it, sending waves across the ocean.', 'Tsunamis behave differently from ordinary wind-driven waves. They may be hard to notice in deep water but grow much higher near shore. The first wave is not always the largest.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '0ebbaafc-f24d-5601-8c9a-140abf0b3b54' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '7518bbcc-00e0-5ec4-b1f5-b273e5a4dfc8', '0ebbaafc-f24d-5601-8c9a-140abf0b3b54', 'vi', 'Sóng thần', 'Sóng thần là một chuỗi sóng dài do một lượng nước lớn dịch chuyển đột ngột. Động đất dưới biển có thể làm đáy biển chuyển động và đẩy khối nước phía trên, tạo sóng lan qua đại dương.', 'Sóng thần khác sóng thông thường do gió tạo ra. Ngoài biển sâu, sóng có thể khó nhận thấy nhưng cao lên nhiều khi đến gần bờ. Đợt sóng đầu tiên không phải lúc nào cũng lớn nhất.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '0ebbaafc-f24d-5601-8c9a-140abf0b3b54' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '39ccdef0-a6e3-571d-a778-f711b5470cb2', '0ebbaafc-f24d-5601-8c9a-140abf0b3b54', 'en', 'Is a tsunami one wave or a series of waves?', 'A series of long waves.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '0ebbaafc-f24d-5601-8c9a-140abf0b3b54' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
