    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'bf7534cb-c3e2-58c4-8c0f-93bd7b55ef99', '11620707-1f01-5ba7-a7a5-e5918d6b02ba', 'en', 'Phu Quoc National Park', 'Phú Quốc National Park protects wooded hills and streams in the north of Phú Quốc Island. Its habitats include evergreen broadleaf forest, Melaleuca forest and mangroves.', 'Mangroves grow along salty, tidal coasts; evergreen forest grows inland.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '11620707-1f01-5ba7-a7a5-e5918d6b02ba' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '1ccc1830-3392-5a47-a9f9-8b0d1010940c', '11620707-1f01-5ba7-a7a5-e5918d6b02ba', 'vi', 'Vườn quốc gia Phú Quốc', 'Vườn quốc gia Phú Quốc bảo vệ đồi rừng và suối ở phía bắc đảo Phú Quốc. Các sinh cảnh có rừng lá rộng thường xanh, rừng tràm và rừng ngập mặn.', 'Rừng ngập mặn mọc ven biển có nước mặn và thủy triều; rừng thường xanh phát triển trong đất liền.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '11620707-1f01-5ba7-a7a5-e5918d6b02ba' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
