    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '1c7fba7e-f2c5-5e04-9038-87c4adb7bd26', '159c7a54-3110-5a25-96ac-fc522868be69', 'en', 'Can Gio Mangrove Forest', 'Cần Giờ is a coastal mangrove forest southeast of central Ho Chi Minh City. River water mixes with seawater here, creating brackish water. Its muddy shores support mangrove trees, fish, shellfish and other wildlife.', 'After wartime destruction, a large replanting programme restored much of the mangrove forest. Cần Giờ became a UNESCO biosphere reserve in 2000.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '159c7a54-3110-5a25-96ac-fc522868be69' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'ab4f5b6a-e694-5947-998f-59b8df393af0', '159c7a54-3110-5a25-96ac-fc522868be69', 'vi', 'Rừng ngập mặn Cần Giờ', 'Cần Giờ là rừng ngập mặn ven biển ở phía đông nam trung tâm Thành phố Hồ Chí Minh. Nước sông hòa với nước biển tạo thành nước lợ. Bờ bùn là nơi sống của cây ngập mặn, cá, các loài có vỏ và nhiều động vật khác.', 'Sau khi rừng bị chiến tranh tàn phá, chương trình trồng lại quy mô lớn đã phục hồi nhiều diện tích rừng ngập mặn. Cần Giờ trở thành khu dự trữ sinh quyển UNESCO năm 2000.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '159c7a54-3110-5a25-96ac-fc522868be69' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '84343ab6-2e4a-555a-950d-4166f00e6358', '159c7a54-3110-5a25-96ac-fc522868be69', 'en', 'What makes the water at Cần Giờ brackish?', 'Fresh river water mixes with seawater.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '159c7a54-3110-5a25-96ac-fc522868be69' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
