    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '8d78cc74-f202-5dc5-b5ab-be9dc02cf4e5', '191b1dd0-e459-59e2-9477-aaf4c1c33606', 'en', 'Northern Lights', 'The northern lights are glowing shapes high above Earth. They appear when energetic charged particles collide with gases in the upper atmosphere. Earth’s magnetic field guides many of these particles toward the polar regions.', 'Oxygen can produce green or red light, while nitrogen can produce blue or pink light. The same kind of display in the Southern Hemisphere is called the southern lights.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '191b1dd0-e459-59e2-9477-aaf4c1c33606' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '1fa87cd9-a3c7-56cc-8ccc-0d4ec6ea996c', '191b1dd0-e459-59e2-9477-aaf4c1c33606', 'vi', 'Bắc cực quang', 'Bắc cực quang là những dải sáng xuất hiện rất cao trên bầu trời. Chúng hình thành khi các hạt mang điện giàu năng lượng va vào khí ở tầng khí quyển trên cao. Từ trường Trái Đất dẫn nhiều hạt về vùng cực.', 'Oxy có thể phát ánh sáng xanh lá hoặc đỏ; nitơ có thể phát ánh sáng xanh lam hoặc hồng. Hiện tượng tương tự ở Nam bán cầu được gọi là nam cực quang.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '191b1dd0-e459-59e2-9477-aaf4c1c33606' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '16cc4db0-af5f-576e-9186-e28ad05e2585', '191b1dd0-e459-59e2-9477-aaf4c1c33606', 'en', 'What makes gases glow during the northern lights?', 'Collisions with energetic charged particles.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '191b1dd0-e459-59e2-9477-aaf4c1c33606' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
