    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'f348c53d-efcc-593a-9938-0ca29ad23bdf', '21ca37d9-9322-580a-a7b0-596b2f68db2f', 'en', 'Pyramids of Giza', 'The three main pyramids at Giza stand near Cairo in Egypt. They were built as royal tombs for Khufu, Khafre and Menkaure during the Old Kingdom, more than four thousand years ago.', 'The largest is the Great Pyramid of Khufu. Each main pyramid belonged to a burial complex that also included temples and other structures.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '21ca37d9-9322-580a-a7b0-596b2f68db2f' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '1f1bac00-b8b9-535a-8578-2974e69e880e', '21ca37d9-9322-580a-a7b0-596b2f68db2f', 'vi', 'Các kim tự tháp Giza', 'Ba kim tự tháp chính ở Giza nằm gần Cairo, Ai Cập. Chúng được xây làm lăng cho các vua Khufu, Khafre và Menkaure vào thời Cổ Vương quốc, cách đây hơn bốn nghìn năm.', 'Lớn nhất là Đại kim tự tháp của vua Khufu. Mỗi kim tự tháp chính thuộc một quần thể mai táng có cả đền và các công trình khác.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '21ca37d9-9322-580a-a7b0-596b2f68db2f' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
