    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '89516cab-55ec-5cc6-94e1-34c10724aa02', '2a0d175c-d3ec-57ef-a37a-e69ea3c33e23', 'en', 'Hailstorm', 'A hailstorm drops lumps of ice called hailstones. Inside a thunderstorm, rising air can hold ice high in the cold cloud, where supercooled water droplets freeze onto it and make it grow.', 'When a hailstone becomes too heavy for the rising air to support, it falls. This explains why ice can reach the ground even during a storm on a warm day.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '2a0d175c-d3ec-57ef-a37a-e69ea3c33e23' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'a68accd0-8868-58fd-b446-59221d9cadc4', '2a0d175c-d3ec-57ef-a37a-e69ea3c33e23', 'vi', 'Mưa đá', 'Mưa đá làm rơi xuống những cục băng gọi là hạt mưa đá. Trong mây dông, luồng khí đi lên có thể giữ băng ở vùng lạnh trên cao. Những giọt nước siêu lạnh đóng băng lên bề mặt, khiến hạt lớn dần.', 'Khi hạt mưa đá quá nặng để luồng khí nâng đỡ, nó rơi xuống. Vì vậy, băng vẫn có thể chạm đất trong một cơn dông vào ngày trời ấm.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '2a0d175c-d3ec-57ef-a37a-e69ea3c33e23' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
