    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '0efea492-2f90-5c7c-96f8-949223cc2189', '2c38278d-8416-5abb-af77-1920733ee701', 'en', 'Sagrada Familia', 'Sagrada Família is a basilica in Barcelona, Spain, designed largely by Antoni Gaudí. Inside, stone columns branch like trees to support the roof.', 'Construction began in 1882. Gaudí took over the project in 1883.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '2c38278d-8416-5abb-af77-1920733ee701' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
