    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '4672a00b-a89d-5ffc-9c5c-0c208d515625', '2d9ffbe0-d096-54bb-b2f8-dfdfa2320767', 'en', 'Dong Nai River', 'The Đồng Nai River’s headwaters rise in the mountainous Lang Biang region of southern Vietnam. The river flows from the highlands toward the lowlands near Ho Chi Minh City.', 'Its basin includes the main river, tributaries and land draining into them. Forest cover in the headwaters helps limit soil erosion, reducing the soil washed into streams after rain.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '2d9ffbe0-d096-54bb-b2f8-dfdfa2320767' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'a0002cf0-b667-5b3f-866a-7494134be11c', '2d9ffbe0-d096-54bb-b2f8-dfdfa2320767', 'vi', 'Sông Đồng Nai', 'Đầu nguồn sông Đồng Nai nằm ở miền núi Lang Biang, phía nam Việt Nam. Sông chảy từ cao nguyên xuống vùng thấp gần Thành phố Hồ Chí Minh.', 'Lưu vực gồm dòng chính, các nhánh sông và vùng đất có nước chảy vào chúng. Rừng đầu nguồn giúp hạn chế xói mòn đất, giảm lượng đất bị nước mưa cuốn xuống suối.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '2d9ffbe0-d096-54bb-b2f8-dfdfa2320767' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
