    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'b8d2480d-36bd-58d3-9e63-cca889dde1c1', '34fb3970-ba64-5786-bebc-9cc83c50d1d4', 'en', 'Vinh Trang Temple', 'Vĩnh Tràng is a Buddhist pagoda in Mỹ Tho in the Mekong Delta. Its halls form a layout resembling the character Quốc (国). The exterior combines Vietnamese decoration with Asian and European architectural details, including arched doorways.', 'The pagoda began in the nineteenth century. The monk Huệ Đăng rebuilt it in 1849.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '34fb3970-ba64-5786-bebc-9cc83c50d1d4' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'd38fe27a-e3b9-5eb7-908a-d07394365654', '34fb3970-ba64-5786-bebc-9cc83c50d1d4', 'vi', 'Chùa Vĩnh Tràng', 'Vĩnh Tràng là chùa Phật giáo ở Mỹ Tho, Đồng bằng sông Cửu Long. Các gian nhà bố trí theo hình chữ Quốc (国). Bên ngoài kết hợp trang trí Việt Nam với chi tiết kiến trúc Á và Âu, trong đó có cửa vòm.', 'Chùa có từ thế kỷ mười chín. Hòa thượng Huệ Đăng xây dựng lại chùa năm 1849.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '34fb3970-ba64-5786-bebc-9cc83c50d1d4' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
