    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '22658841-428b-5c8d-9add-bb29cd811cf9', '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe', 'en', 'Black ice', 'Black ice is a thin, hard-to-see layer of ice on a road or other surface. The ice is usually clear, so the dark pavement beneath it can make the surface look merely wet.', 'Rainwater or melted snow can refreeze when a road cools below freezing. Freezing fog can also leave ice. Bridges and overpasses can freeze before other road surfaces.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'd766db8d-86a3-511e-994f-fa07275d7b19', '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe', 'vi', 'Băng mỏng trong suốt', 'Black ice là lớp băng mỏng rất khó thấy trên đường hoặc bề mặt khác. Băng thường trong suốt, nên mặt đường sẫm màu bên dưới có thể khiến người nhìn tưởng đường chỉ bị ướt.', 'Nước mưa hoặc tuyết tan có thể đóng băng lại khi mặt đường lạnh xuống dưới điểm đóng băng. Sương mù đóng băng cũng có thể để lại băng. Cầu và cầu vượt có thể đóng băng trước các mặt đường khác.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT 'cc772015-3df7-57bd-8711-c91a02ad57d4', '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe', 'en', 'Why can black ice look like wet, dark pavement?', 'The ice is clear, allowing the dark road underneath to show through.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT 'e0a78c4e-23c2-5231-a8e5-9b040c14949c', '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe', 'vi', 'Vì sao black ice có thể trông như mặt đường sẫm màu bị ướt?', 'Băng trong suốt nên nhìn xuyên thấy mặt đường sẫm màu bên dưới.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '885e6805-7e7c-5f2c-b82d-4c7b0879c68b', '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe', 'en', 'What can happen to rainwater on a road when its surface drops below freezing?', 'The water can freeze into a hard-to-see ice layer.', NULL, 1, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '4fcbac76-214e-59f3-bd2c-e68dc7d9e2fe' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
