    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '8902f331-9bc7-5bf8-8cef-080aa52d3d23', '5b437ba0-80b6-5385-b3e0-d027dcc2ec63', 'en', 'Tan Dinh church', 'Tân Định Church stands on Hai Bà Trưng Street in Ho Chi Minh City. Its Romanesque design includes Gothic and Renaissance elements, with arched openings and a tall bell tower.', 'The church opened in 1876. It acquired its distinctive pink exterior during renovation in 1957.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '5b437ba0-80b6-5385-b3e0-d027dcc2ec63' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
