    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '2b66bc7f-55c1-543e-a13e-c6fe1964ebb5', '5ca1014f-7f6a-5812-939f-68dbfd6949f3', 'en', 'Old Faithful', 'Old Faithful is a geyser in Yellowstone National Park in the United States. Underground volcanic heat warms water, which escapes in bursts of hot water and steam through narrow passages in the rock.', 'Its eruptions are predictable enough for park staff to estimate the next one, but the waiting time changes. It is neither Yellowstone’s largest geyser nor a clock that erupts at one fixed interval.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '5ca1014f-7f6a-5812-939f-68dbfd6949f3' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '88eb59cb-fe89-597b-8bc1-f17087c1132a', '5ca1014f-7f6a-5812-939f-68dbfd6949f3', 'vi', 'Mạch nước phun Old Faithful', 'Old Faithful là mạch nước phun trong Vườn quốc gia Yellowstone ở Hoa Kỳ. Nhiệt núi lửa dưới lòng đất làm nóng nước. Nước nóng và hơi nước phun lên qua những lối hẹp trong đá.', 'Nhân viên vườn quốc gia có thể ước tính lần phun tiếp theo, nhưng thời gian chờ thay đổi. Đây không phải mạch phun lớn nhất Yellowstone và cũng không phun theo một khoảng thời gian cố định.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '5ca1014f-7f6a-5812-939f-68dbfd6949f3' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
