    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '86abc844-5547-5958-b2d5-890888d9d082', '672946ff-0b3a-58df-9d2e-230cd8179b79', 'en', 'Rock-Hewn Churches of Lalibela', 'Lalibela in Ethiopia has eleven medieval churches carved from rock. Builders removed stone to create walls, doorways and rooms, rather than stacking blocks to make the buildings.', 'The churches are linked by passages and trenches and remain important places of Christian pilgrimage. Their design is associated with King Lalibela’s vision of a New Jerusalem in Ethiopia.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '672946ff-0b3a-58df-9d2e-230cd8179b79' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '63f62ace-d7bd-5b44-a3a4-b30e75a3c1e4', '672946ff-0b3a-58df-9d2e-230cd8179b79', 'vi', 'Các nhà thờ đục trong đá ở Lalibela', 'Lalibela ở Ethiopia có mười một nhà thờ thời trung cổ được đục từ đá. Thợ xây lấy đá đi để tạo tường, cửa và phòng, thay vì chồng các khối đá lên thành công trình.', 'Các nhà thờ nối với nhau bằng lối đi và hào, đồng thời vẫn là nơi hành hương quan trọng của tín đồ Kitô giáo. Thiết kế gắn với ý tưởng của vua Lalibela về một Jerusalem mới tại Ethiopia.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '672946ff-0b3a-58df-9d2e-230cd8179b79' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
