    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '04782777-37ac-5391-acac-de8ee94d50cb', '72b568e9-b705-5762-b2f5-cbee860f4f68', 'en', 'Saigon Notre-Dame Basilica', 'Notre-Dame Cathedral Basilica of Saigon is a Catholic cathedral in central Ho Chi Minh City. It has red-brick walls and two bell towers.', 'The cathedral was built between 1877 and 1880 using construction materials imported from France.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '72b568e9-b705-5762-b2f5-cbee860f4f68' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '75d7c427-d6b1-56e6-bcc4-ea1847642657', '72b568e9-b705-5762-b2f5-cbee860f4f68', 'vi', 'Nhà thờ Đức Bà Sài Gòn', 'Nhà thờ Đức Bà Sài Gòn là nhà thờ chính tòa Công giáo ở trung tâm Thành phố Hồ Chí Minh. Công trình có tường gạch đỏ và hai tháp chuông.', 'Nhà thờ được xây từ năm 1877 đến năm 1880, sử dụng vật liệu xây dựng nhập từ Pháp.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '72b568e9-b705-5762-b2f5-cbee860f4f68' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
