    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '5e588dce-4865-5e76-af18-5d9eb063472e', '8e871ce5-0b47-554f-913f-3ec551441e0d', 'en', 'Tomb of Khai Dinh', 'Khải Định’s tomb stands on a hillside near Huế. Dark stone steps lead past statues outside. Inside, ceramic and coloured-glass mosaics decorate the walls.', 'Construction lasted from 1920 to 1931. The tomb combines Vietnamese and European design influences.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '8e871ce5-0b47-554f-913f-3ec551441e0d' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '7a29c63a-6628-5c5f-96dd-17440e73938a', '8e871ce5-0b47-554f-913f-3ec551441e0d', 'vi', 'Lăng Khải Định', 'Lăng Khải Định nằm trên sườn đồi gần Huế. Bậc đá sẫm màu đi qua các tượng bên ngoài. Bên trong, tranh ghép bằng sành sứ và thủy tinh màu trang trí tường.', 'Công trình được xây từ năm 1920 đến năm 1931. Lăng kết hợp ảnh hưởng thiết kế Việt Nam và châu Âu.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '8e871ce5-0b47-554f-913f-3ec551441e0d' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
