    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '403e7bd6-7c56-5f69-90fe-17492a310d54', '9f26e81f-5100-51c3-a896-a31323b077bb', 'en', 'El Niño', 'During El Niño, the surface of the central and eastern tropical Pacific is unusually warm. Weakening trade winds allow warm surface water to spread eastward.', 'El Niño is the warm phase of ENSO, the El Niño–Southern Oscillation. Changes in ocean heat and air circulation can alter rainfall and weather far beyond the Pacific.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '9f26e81f-5100-51c3-a896-a31323b077bb' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'cd8c483c-808b-5ba9-9e07-06036955bbab', '9f26e81f-5100-51c3-a896-a31323b077bb', 'vi', 'El Niño', 'Trong El Niño, nước mặt ở vùng nhiệt đới trung tâm và phía đông Thái Bình Dương ấm bất thường. Gió tín phong yếu đi cho phép nước ấm trên mặt biển lan về phía đông.', 'El Niño là pha nóng của ENSO, tức El Niño–Dao động phương Nam. Thay đổi nhiệt đại dương và hoàn lưu không khí có thể làm đổi mưa cùng thời tiết ở nhiều nơi xa Thái Bình Dương.' WHERE EXISTS (SELECT 1 FROM items WHERE id = '9f26e81f-5100-51c3-a896-a31323b077bb' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '4f7a255e-2b9a-5098-9860-645d95946d79', '9f26e81f-5100-51c3-a896-a31323b077bb', 'en', 'Is El Niño the whole ENSO climate pattern or one phase of it?', 'It is the warm phase of ENSO, not the whole pattern.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '9f26e81f-5100-51c3-a896-a31323b077bb' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '4301a39a-2367-5891-b184-3f3fde2acca2', '9f26e81f-5100-51c3-a896-a31323b077bb', 'vi', 'El Niño là toàn bộ kiểu biến động khí hậu ENSO hay một pha của nó?', 'El Niño là pha nóng của ENSO, không phải toàn bộ kiểu biến động.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = '9f26e81f-5100-51c3-a896-a31323b077bb' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
