    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'd9b0aa3d-0e17-5fd0-84ae-cad5052a4631', 'a509b503-b70e-5f3d-89d0-001db7aa0448', 'en', 'Polar Bear', 'Polar bears live in the Arctic and hunt seals from sea ice. Beneath their pale-looking fur, their skin is black. Their large front paws help them swim between patches of ice.', 'A bear may wait beside a seal’s breathing hole to catch its meal. When sea ice melts earlier, the bear has less time to hunt and build up its energy reserves.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'a509b503-b70e-5f3d-89d0-001db7aa0448' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'ad308d6c-0343-5ede-b3f8-c0917b69c521', 'a509b503-b70e-5f3d-89d0-001db7aa0448', 'vi', 'Gấu Bắc Cực', 'Gấu Bắc Cực sống ở vùng Bắc Cực và săn hải cẩu trên băng biển. Dưới bộ lông trông có vẻ trắng là làn da đen. Hai bàn chân trước lớn giúp gấu bơi giữa các mảng băng.', 'Gấu có thể chờ bên lỗ thở của hải cẩu để bắt mồi. Khi băng biển tan sớm hơn, gấu có ít thời gian săn mồi và tích trữ năng lượng hơn.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'a509b503-b70e-5f3d-89d0-001db7aa0448' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
