    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'bc70ad7f-4bdb-558e-844c-3d8a24c5a1a6', 'a5ef336f-a275-5a37-a0e0-9a32d73f9828', 'en', 'Airglow', 'Airglow is faint light made by gases high in Earth’s atmosphere. Sunlight supplies energy to these gases, and processes involving their atoms and molecules release some of that energy as visible light.', 'Different gases and altitude layers produce different airglow colours, which scientists use to study the upper atmosphere. Airglow occurs across the globe and is often too faint for the eye to notice.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'a5ef336f-a275-5a37-a0e0-9a32d73f9828' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'b2d80a5e-2d8d-5933-b42f-9398b0317653', 'a5ef336f-a275-5a37-a0e0-9a32d73f9828', 'vi', 'Ánh sáng khí quyển', 'Ánh sáng khí quyển là ánh sáng mờ do khí ở tầng cao của khí quyển Trái Đất tạo ra. Ánh nắng cung cấp năng lượng; các quá trình liên quan đến nguyên tử và phân tử giải phóng một phần năng lượng ấy thành ánh sáng nhìn thấy được.', 'Các loại khí và lớp độ cao khác nhau tạo màu ánh sáng khí quyển khác nhau, giúp các nhà khoa học nghiên cứu khí quyển trên cao. Hiện tượng xuất hiện khắp thế giới và thường quá mờ để mắt nhận thấy.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'a5ef336f-a275-5a37-a0e0-9a32d73f9828' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '3a849475-4b24-5045-bb2d-ea03d5e0e05b', 'a5ef336f-a275-5a37-a0e0-9a32d73f9828', 'en', 'What supplies much of the energy behind airglow?', 'Sunlight.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'a5ef336f-a275-5a37-a0e0-9a32d73f9828' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
