    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'af7725b0-39a7-580e-acc2-e4e5e9975f12', 'aa751bee-d953-5e19-bfcd-bd36511f9e66', 'en', 'Torres del Paine', 'Torres del Paine lies in southern Chile, between the Andes and the Patagonian steppe. Its landscape includes mountains, glaciers, lakes and rivers. Guanacos, wild relatives of llamas, live in the park.', 'Plants in the wind-exposed scrubland conserve water, while forests grow under different conditions. Torres del Paine became a UNESCO biosphere reserve in 1978.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'aa751bee-d953-5e19-bfcd-bd36511f9e66' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '6073abd4-d36e-56ab-885f-9642abeacc55', 'aa751bee-d953-5e19-bfcd-bd36511f9e66', 'vi', 'Torres del Paine', 'Torres del Paine nằm ở miền nam Chile, giữa dãy Andes và thảo nguyên Patagonia. Cảnh quan có núi, sông băng, hồ và sông. Guanaco, họ hàng hoang dã của lạc đà không bướu llama, sống trong vườn quốc gia.', 'Cây ở vùng cây bụi nhiều gió có đặc điểm giúp tiết kiệm nước, còn rừng phát triển trong điều kiện khác. Torres del Paine trở thành khu dự trữ sinh quyển UNESCO năm 1978.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'aa751bee-d953-5e19-bfcd-bd36511f9e66' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '6a769815-3013-5fa8-a377-4f835bdb2c81', 'aa751bee-d953-5e19-bfcd-bd36511f9e66', 'en', 'Between which two landscapes does Torres del Paine lie?', 'The Andes and the Patagonian steppe, in southern Chile.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'aa751bee-d953-5e19-bfcd-bd36511f9e66' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
