    INSERT INTO quiz_questions (id, item_id, lang, question, question_type, options, correct_answers, sort_order, is_active, question_group_id) SELECT '8d83a19a-0959-5025-9019-27fd9d73b8a1', 'aa751bee-d953-5e19-bfcd-bd36511f9e66', 'vi', 'Đặc điểm nào giúp cây vùng cây bụi Torres del Paine thích nghi với gió mạnh?', 'single', '["Lá rộng, mềm dễ mất nước nhanh","Rễ thích nghi với ngập thủy triều thường xuyên","Đặc điểm giúp tiết kiệm nước"]', '[2]', 0, TRUE, '0eb20a90-73f4-5936-bf5c-5300d1e6f101' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'aa751bee-d953-5e19-bfcd-bd36511f9e66' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, question = EXCLUDED.question, question_type = EXCLUDED.question_type, options = EXCLUDED.options, correct_answers = EXCLUDED.correct_answers, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, question_group_id = EXCLUDED.question_group_id;
