    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'a5291e81-cc4c-534b-8400-61117848ac67', 'ae714628-c0bd-5472-bcde-c4fdd2675191', 'en', 'Mekong River', 'The Mekong begins on the Tibetan Plateau and travels through or along six countries: China, Myanmar, Laos, Thailand, Cambodia and Vietnam. Its river system connects mountain streams with floodplains and the Mekong Delta.', 'The river supports fishing, farming and transport. Its water also carries sediment that helps build and nourish land downstream. Changes upstream can affect communities far away, so neighbouring countries need to cooperate.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'ae714628-c0bd-5472-bcde-c4fdd2675191' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '9e9a3503-fdde-5b3e-99cd-48b102406b35', 'ae714628-c0bd-5472-bcde-c4fdd2675191', 'vi', 'Sông Mê Công', 'Sông Mê Công bắt nguồn từ cao nguyên Tây Tạng, chảy qua hoặc dọc biên giới sáu nước: Trung Quốc, Myanmar, Lào, Thái Lan, Campuchia và Việt Nam. Hệ thống sông nối các dòng suối miền núi với đồng bằng và vùng châu thổ.', 'Dòng sông phục vụ đánh cá, trồng trọt và giao thông. Nước còn mang phù sa giúp bồi đắp và nuôi dưỡng đất ở hạ lưu. Thay đổi ở thượng nguồn có thể ảnh hưởng nơi xa, nên các nước cần hợp tác.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'ae714628-c0bd-5472-bcde-c4fdd2675191' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT 'c5c4ab82-820b-5d24-bc85-c27c96d01a06', 'ae714628-c0bd-5472-bcde-c4fdd2675191', 'en', 'Where does the Mekong River begin?', 'On the Tibetan Plateau.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'ae714628-c0bd-5472-bcde-c4fdd2675191' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
