    INSERT INTO quiz_questions (id, item_id, lang, question, question_type, options, correct_answers, sort_order, is_active, question_group_id) SELECT 'ecf09b7a-ab93-5775-987d-66d5d72170b0', 'ae714628-c0bd-5472-bcde-c4fdd2675191', 'en', 'Why do countries sharing the Mekong need to cooperate?', 'single', '["Each country receives water from an independent source","Upstream changes can affect downstream communities","Only the country at the river mouth uses its water"]', '[1]', 1, TRUE, 'ece08b53-8b4d-5349-9aca-dbf2d52a612c' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'ae714628-c0bd-5472-bcde-c4fdd2675191' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, question = EXCLUDED.question, question_type = EXCLUDED.question_type, options = EXCLUDED.options, correct_answers = EXCLUDED.correct_answers, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, question_group_id = EXCLUDED.question_group_id;
