    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '013a437d-a037-5bd0-be41-b8af98eb211d', 'af9ac691-e1d2-5dad-a975-7138695fa5e1', 'en', 'Reed Flute Cave', 'Reed Flute Cave is a limestone cave near Guilin in southern China. Mineral-rich water leaves deposits that form stalactites hanging from the ceiling and stalagmites growing from the floor. These formations can join into stone pillars.', 'Inscriptions inside the cave include poems and travel records from the Tang dynasty. Coloured lamps illuminate the cave today; they supply the vivid display colours, not the minerals themselves.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'af9ac691-e1d2-5dad-a975-7138695fa5e1' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '41208b9e-0d30-5a6e-b171-3cd02ec57009', 'af9ac691-e1d2-5dad-a975-7138695fa5e1', 'vi', 'Động Sáo Sậy', 'Động Sáo Sậy là hang đá vôi gần Quế Lâm, miền nam Trung Quốc. Nước mang khoáng chất để lại lớp lắng đọng, tạo nhũ đá rủ từ trần và măng đá mọc từ nền hang. Chúng có thể nối thành cột đá.', 'Chữ khắc trong hang có thơ và ghi chép của khách đến thăm từ thời nhà Đường. Ngày nay, đèn màu chiếu sáng hang; màu sắc rực rỡ khi tham quan đến từ đèn, không phải màu của khoáng chất.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'af9ac691-e1d2-5dad-a975-7138695fa5e1' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '467d8559-23db-59eb-9118-e29f0d547c62', 'af9ac691-e1d2-5dad-a975-7138695fa5e1', 'en', 'What rock forms Reed Flute Cave near Guilin?', 'Limestone.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'af9ac691-e1d2-5dad-a975-7138695fa5e1' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '674d0ec5-8dd6-58d0-a81a-b1d89db04751', 'af9ac691-e1d2-5dad-a975-7138695fa5e1', 'vi', 'Động Sáo Sậy gần Quế Lâm hình thành trong loại đá nào?', 'Đá vôi.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'af9ac691-e1d2-5dad-a975-7138695fa5e1' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
