    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '9471622d-96b9-5037-af8a-a3cb12289082', 'b74e0047-d2c7-51b8-956e-ab3a6b461de3', 'en', 'Waterspout', 'A waterspout is a rotating column of air over water, often visible as a funnel below a cloud. It can lift spray from the surface, but the funnel is not simply a tube of seawater.', 'Tornadic waterspouts develop downward from tornado-producing thunderstorms. Fair-weather waterspouts develop upward from the water surface beneath growing clouds.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'b74e0047-d2c7-51b8-956e-ab3a6b461de3' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '14d8673d-c8d9-5023-952b-0480d01b1a4b', 'b74e0047-d2c7-51b8-956e-ab3a6b461de3', 'vi', 'Vòi rồng trên mặt nước', 'Vòi rồng trên mặt nước là cột không khí xoay phía trên biển hoặc hồ, thường hiện thành phễu dưới mây. Nó có thể cuốn bụi nước lên, nhưng phễu không đơn giản là một ống nước biển.', 'Vòi rồng kiểu lốc xoáy phát triển từ mây dông tạo lốc đi xuống. Loại thường gọi là vòi rồng thời tiết đẹp phát triển từ mặt nước đi lên dưới các đám mây đang lớn.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'b74e0047-d2c7-51b8-956e-ab3a6b461de3' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
