    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'adb837e5-c6d0-5f2c-a2eb-b9ed06bbf1dc', 'bbb82d32-955b-56a0-8e4a-f2f22a1b5fc7', 'en', 'Ngọ Môn', 'Ngọ Môn is the main entrance to Huế’s Imperial City. The Ngũ Phụng pavilion stands above the gateway. Historically, the central passage was reserved for the emperor.', 'The gate was built in 1833 under Emperor Minh Mạng, during a reorganisation of the Imperial City.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'bbb82d32-955b-56a0-8e4a-f2f22a1b5fc7' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'c25d4766-5b86-5f48-abd6-856cdc7f33bf', 'bbb82d32-955b-56a0-8e4a-f2f22a1b5fc7', 'vi', 'Ngọ Môn', 'Ngọ Môn là lối vào chính của Hoàng thành Huế. Lầu Ngũ Phụng nằm phía trên phần cổng. Trước đây, lối giữa dành riêng cho nhà vua.', 'Cổng được xây năm 1833 dưới triều vua Minh Mạng, khi triều đình quy hoạch lại Hoàng thành.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'bbb82d32-955b-56a0-8e4a-f2f22a1b5fc7' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
