    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '25192609-73f5-5be1-8af4-a31e2f90c17f', 'c1033dab-122d-544d-9dca-7536577d24be', 'en', 'Imperial City of Hue', 'Huế’s Imperial City was the royal precinct inside the larger capital citadel. The Forbidden Purple City lay within it. Palaces, temples and courtyards served the Nguyễn court’s ceremonies and administration.', 'Huế was the Nguyễn dynasty’s capital from 1802 to 1945. The Imperial City forms part of the Complex of Hué Monuments, inscribed on UNESCO’s World Heritage List in 1993.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'c1033dab-122d-544d-9dca-7536577d24be' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '06051be4-e867-5484-9011-b6cee2893b7a', 'c1033dab-122d-544d-9dca-7536577d24be', 'vi', 'Hoàng thành Huế', 'Hoàng thành Huế là khu vực cung đình bên trong Kinh thành rộng lớn hơn. Tử Cấm Thành nằm trong Hoàng thành. Cung điện, đền miếu và sân phục vụ nghi lễ cùng việc triều chính của nhà Nguyễn.', 'Huế là kinh đô triều Nguyễn từ năm 1802 đến năm 1945. Hoàng thành thuộc Quần thể di tích Cố đô Huế, được UNESCO ghi danh Di sản Thế giới năm 1993.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'c1033dab-122d-544d-9dca-7536577d24be' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
