    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'f01e1030-b043-5297-9762-472c4839c416', 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66', 'en', 'Hurricane', 'A hurricane is a powerful tropical cyclone. Bands of rain curve around its centre. In a well-developed storm, a relatively calm eye is surrounded by an eyewall with intense rain and very strong winds.', 'The calm inside the eye does not mean the storm has ended. As the cyclone moves, the other side of the eyewall can bring dangerous conditions again.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '7b7972ee-6b31-5c62-8d49-c0ba54972a4c', 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66', 'vi', 'Bão nhiệt đới — hurricane', 'Hurricane là tên gọi một loại xoáy thuận nhiệt đới mạnh. Các dải mưa cuộn quanh tâm bão. Khi bão phát triển rõ, mắt bão tương đối yên được bao quanh bởi thành mắt bão có mưa dữ dội và gió rất mạnh.', 'Sự yên lặng trong mắt bão không có nghĩa là bão đã qua. Khi bão di chuyển, phía bên kia thành mắt bão có thể lại mang đến thời tiết nguy hiểm.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '245061bd-68cf-58bf-80de-b88bdd72f0a9', 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66', 'en', 'Which part of a well-developed hurricane can be relatively calm?', 'The eye.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'd347cd58-0a5b-5dca-9e65-70b8f75b9b66' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
