    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '05af3759-5615-5225-8a45-7b4e6cbdf5f7', 'd56fdbca-2cdf-5513-af97-c69d63f6937c', 'en', 'Dau Tieng Reservoir', 'Dầu Tiếng is a reservoir in southern Vietnam, created by holding water behind a dam. Its irrigation system carries water to farmland. The reservoir also supplies water for treatment plants serving towns and cities.', 'Freshwater released downstream helps push salty water back during dry periods.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'd56fdbca-2cdf-5513-af97-c69d63f6937c' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'c1db3234-3145-5f6f-9ed9-18f8997a1588', 'd56fdbca-2cdf-5513-af97-c69d63f6937c', 'vi', 'Hồ Dầu Tiếng', 'Dầu Tiếng là hồ chứa ở miền nam Việt Nam, được tạo bằng cách giữ nước sau đập. Hệ thống thủy lợi đưa nước đến đồng ruộng. Hồ còn cấp nước cho các nhà máy xử lý nước phục vụ đô thị.', 'Nước ngọt xả xuống hạ lưu giúp đẩy nước mặn trở lại trong thời kỳ khô hạn.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'd56fdbca-2cdf-5513-af97-c69d63f6937c' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
