    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'ebbee69a-d263-5c19-badd-d669c8bc842e', 'e49c000b-0b6e-577b-afc3-18697dcd272d', 'en', 'Christ the Redeemer', 'Christ the Redeemer stands with outstretched arms on Corcovado mountain above Rio de Janeiro, Brazil. The statue is an example of Art Deco, a style that often uses bold, simplified shapes.', 'Brazilian engineer Heitor da Silva Costa led the project. Construction began in 1926, and the statue opened in 1931.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'e49c000b-0b6e-577b-afc3-18697dcd272d' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '15c5be85-4cb8-51a2-aa38-f048cf2ec520', 'e49c000b-0b6e-577b-afc3-18697dcd272d', 'vi', 'Tượng Chúa Kitô Cứu Thế', 'Tượng Chúa Kitô Cứu Thế dang hai tay trên núi Corcovado, phía trên thành phố Rio de Janeiro, Brazil. Tượng thuộc phong cách Art Deco, thường dùng những hình khối rõ nét và giản lược.', 'Kỹ sư Brazil Heitor da Silva Costa phụ trách dự án. Công trình bắt đầu xây năm 1926 và khánh thành năm 1931.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'e49c000b-0b6e-577b-afc3-18697dcd272d' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
