    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT 'e6d8c3fd-d0f1-5e5b-80ec-ce8547d3a667', 'f6c5e715-2e3d-5fdb-98bd-c0ff1e903fbe', 'en', 'Perfume Pagoda', 'Chùa Hương is a group of Buddhist temples, shrines and caves in the limestone mountains southwest of Hanoi. Hương Tích Cave contains the complex’s principal cave shrine.', 'During the spring pilgrimage season, visitors travel by boat along Yến Stream before continuing toward the temples and cave.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f6c5e715-2e3d-5fdb-98bd-c0ff1e903fbe' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '7155bce3-d6f5-502c-8c26-c998d4523ae0', 'f6c5e715-2e3d-5fdb-98bd-c0ff1e903fbe', 'vi', 'Chùa Hương', 'Chùa Hương là quần thể chùa, đền và hang động Phật giáo trong vùng núi đá vôi phía tây nam Hà Nội. Động Hương Tích có ngôi chùa trong hang quan trọng nhất của quần thể.', 'Vào mùa hành hương đầu xuân, khách đi thuyền dọc suối Yến rồi tiếp tục đến các chùa và hang.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f6c5e715-2e3d-5fdb-98bd-c0ff1e903fbe' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
