    INSERT INTO items (id, category, latitude, longitude, country_code, icon_slug, is_published, source_type, recipe, location_desc, fun_facts, audio_urls, youtube_url, trailer_url, characters, start_year, end_year, time_precision, released_date, rich_fields, franchise_id, quiz_required, catalog_content_hash) VALUES ('f819b0a2-8772-5699-b364-0598070827b0', 'phenomenon', 40.7128, -74.006, 'US', 'phenomenon', TRUE, 'system', NULL, NULL, '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"sources":[{"url":"https://en.wikipedia.org/wiki/Atmospheric_refraction","publisher":"Wikipedia — Atmospheric refraction","accessed_at":"2026-10-23"},{"url":"https://en.wikipedia.org/wiki/Mirage","publisher":"Wikipedia — Mirage","accessed_at":"2026-10-23"},{"url":"https://cloudatlas.wmo.int/en/mirage.html","publisher":"World Meteorological Organization — mirages","accessed_at":"2026-10-23"},{"url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter6-6/","publisher":"NASA — refraction and the apparent position of the Sun","accessed_at":"2026-10-23"}]}', NULL, TRUE, '19b06708b44d75be974f8d82bfaafdf1103fce301714ce3ac7fbe2bd23e94985') ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, country_code = EXCLUDED.country_code, icon_slug = EXCLUDED.icon_slug, is_published = EXCLUDED.is_published, recipe = EXCLUDED.recipe, location_desc = EXCLUDED.location_desc, fun_facts = EXCLUDED.fun_facts, audio_urls = EXCLUDED.audio_urls, youtube_url = EXCLUDED.youtube_url, trailer_url = EXCLUDED.trailer_url, characters = EXCLUDED.characters, start_year = EXCLUDED.start_year, end_year = EXCLUDED.end_year, time_precision = EXCLUDED.time_precision, released_date = EXCLUDED.released_date, rich_fields = EXCLUDED.rich_fields, franchise_id = EXCLUDED.franchise_id, quiz_required = EXCLUDED.quiz_required, catalog_content_hash = EXCLUDED.catalog_content_hash, updated_at = CURRENT_TIMESTAMP WHERE items.source_type = 'system';
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '3528a058-aea3-5e74-bf95-7dff1e72110f', 'f819b0a2-8772-5699-b364-0598070827b0', 'en', 'Atmospheric refraction', 'Atmospheric refraction happens when light bends as it travels through air of different densities. Temperature differences can create layers that make distant objects appear shifted, stretched or upside down.', 'Over a hot road, refraction can make light from the sky look like a patch of water on dry ground. Near the horizon, atmospheric refraction also makes the Sun appear higher than its true geometric position.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f819b0a2-8772-5699-b364-0598070827b0' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO item_translations (id, item_id, lang, title, description, history) SELECT '423709e1-88bf-53f8-9022-986502a28bba', 'f819b0a2-8772-5699-b364-0598070827b0', 'vi', 'Khúc xạ khí quyển', 'Khúc xạ khí quyển xảy ra khi ánh sáng đổi hướng lúc đi qua các lớp không khí có mật độ khác nhau. Chênh lệch nhiệt độ có thể tạo các lớp khiến vật ở xa trông lệch vị trí, kéo dài hoặc lộn ngược.', 'Trên đường nóng, khúc xạ có thể khiến ánh sáng từ bầu trời trông như vũng nước trên nền đường khô. Gần chân trời, khúc xạ khí quyển còn khiến Mặt Trời trông cao hơn vị trí hình học thực.' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f819b0a2-8772-5699-b364-0598070827b0' AND source_type = 'system') ON CONFLICT (item_id, lang) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, history = EXCLUDED.history;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT 'cc898618-434e-5370-ac9e-87dc1af3709d', 'f819b0a2-8772-5699-b364-0598070827b0', 'en', 'What happens to light passing through air layers of different densities?', 'Its path can bend: this is atmospheric refraction.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f819b0a2-8772-5699-b364-0598070827b0' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
    INSERT INTO flashcards (id, item_id, lang, front, back, media_hint, sort_order, is_published, source_type) SELECT '1224ce17-e289-5c24-9b27-9199c43ff032', 'f819b0a2-8772-5699-b364-0598070827b0', 'vi', 'Điều gì xảy ra với ánh sáng đi qua các lớp không khí có mật độ khác nhau?', 'Đường đi có thể đổi hướng: đó là khúc xạ khí quyển.', NULL, 0, TRUE, 'catalog_authored' WHERE EXISTS (SELECT 1 FROM items WHERE id = 'f819b0a2-8772-5699-b364-0598070827b0' AND source_type = 'system') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, front = EXCLUDED.front, back = EXCLUDED.back, media_hint = EXCLUDED.media_hint, sort_order = EXCLUDED.sort_order, is_published = EXCLUDED.is_published, source_type = EXCLUDED.source_type, updated_at = CURRENT_TIMESTAMP;
